'use strict';

// MODULES //

var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var objectKeys = require( '@stdlib/utils/keys' );
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var TARGET_TYPES = [
	'code',
	'definition',
	'directive',
	'embedded-code',
	'frontmatter',
	'heading',
	'markdown',
	'math',
	'media',
	'raw',
	'section',
	'summary',
	'thematicBreak',
	'topic'
];


// FUNCTIONS //

/**
* Creates an integrity error.
*
* @private
* @param {string} path - data path
* @param {string} code - error code
* @param {string} message - error message
* @returns {Object} integrity error
*/
function error( path, code, message ) {
	return {
		'keyword': 'semanticIntegrity',
		'dataPath': path,
		'schemaPath': format( '#/semanticIntegrity/%s', code ),
		'params': {
			'code': code
		},
		'message': message
	};
}

/**
* Returns the source envelope for a semantic leaf.
*
* @private
* @param {Object} node - semantic node
* @returns {(Object|null)} source envelope
*/
function envelope( node ) {
	var start;
	var refs;
	var end;
	var r;
	var i;

	if ( node.source.envelope ) {
		return node.source.envelope;
	}
	refs = node.source.refs;
	for ( i = 0; i < refs.length; i++ ) {
		r = refs[ i ].range;
		if ( r ) {
			if ( !start || ( r.start.offset < start.offset ) ) {
				start = r.start;
			}
			if ( !end || ( r.end.offset > end.offset ) ) {
				end = r.end;
			}
		}
	}
	if ( start && end ) {
		return {
			'start': start,
			'end': end
		};
	}
	return null;
}

/**
* Registers a document-local ID.
*
* @private
* @param {string} id - ID
* @param {string} type - target type
* @param {Object} node - registered node
* @param {string} path - data path
* @param {Object} state - validation state
* @returns {void}
*/
function register( id, type, node, path, state ) {
	if ( state.ids[ id ] ) {
		state.errors.push( error( path, 'duplicate-id', 'must be unique within the semantic document' ) );
		return;
	}
	state.ids[ id ] = {
		'id': id,
		'type': type,
		'node': node
	};
}

/**
* Registers flow nodes and checks their source order.
*
* @private
* @param {Array} children - semantic children
* @param {Object} state - validation state
* @param {string} path - data path
* @returns {void}
*/
function flow( children, state, path ) {
	var current;
	var node;
	var p;
	var i;

	for ( i = 0; i < children.length; i++ ) {
		node = children[ i ];
		p = format( '%s[%d]', path, i );
		register( node.id, node.type, node, format( '%s.id', p ), state );
		if ( node.children ) {
			flow( node.children, state, format( '%s.children', p ) );
			continue;
		}
		current = envelope( node );
		if (
			current &&
			state.previous &&
			current.start.offset < state.previous.end.offset
		) {
			state.errors.push( error( format( '%s.source', p ), 'source-order', 'must not precede or overlap the previous semantic leaf' ) );
		}
		if ( current ) {
			state.previous = current;
		}
	}
}

/**
* Checks that a reference resolves to an allowed target type.
*
* @private
* @param {(string|null)} ref - target reference
* @param {string} path - data path
* @param {(string|Array)} types - allowed target type(s)
* @param {Object} state - validation state
* @returns {(Object|null)} resolved target record or null
*/
function reference( ref, path, types, state ) {
	var target;

	if ( ref === null ) {
		return null;
	}
	target = state.ids[ ref ];
	if ( !target ) {
		state.errors.push( error( path, 'unresolved-reference', 'must resolve to a document-local ID' ) );
		return null;
	}
	if ( isString( types ) ) {
		types = [ types ];
	}
	if ( types.indexOf( target.type ) === -1 ) {
		state.errors.push( error( path, 'reference-type', format( 'must resolve to one of the following targets: %s', join( types, ', ' ) ) ) );
		return null;
	}
	return target;
}

/**
* Registers semantic resources.
*
* @private
* @param {Object} doc - semantic document
* @param {Object} state - validation state
* @returns {void}
*/
function resources( doc, state ) {
	var resource;
	var groups;
	var names;
	var types;
	var g;
	var i;
	var j;

	names = [
		'definitions',
		'directives',
		'embeddedCode'
	];
	types = [
		'definition',
		'directive',
		'embedded-code'
	];
	groups = [
		doc.resources.definitions,
		doc.resources.directives,
		doc.resources.embeddedCode
	];
	for ( i = 0; i < groups.length; i++ ) {
		g = groups[ i ];
		for ( j = 0; j < g.length; j++ ) {
			resource = g[ j ];
			register( resource.id, types[ i ], resource, format( '.resources.%s[%d].id', names[ i ], j ), state );
		}
	}
}

/**
* Checks container and leaf references.
*
* @private
* @param {Array} children - semantic children
* @param {Object} state - validation state
* @param {string} path - data path
* @returns {void}
*/
function flowReferences( children, state, path ) {
	var node;
	var p;
	var j;
	var i;

	for ( i = 0; i < children.length; i++ ) {
		node = children[ i ];
		p = format( '%s[%d]', path, i );
		if ( node.type === 'section' || node.type === 'topic' ) {
			reference( node.headingRef, format( '%s.headingRef', p ), 'heading', state );
			flowReferences( node.children, state, format( '%s.children', p ) );
		} else if ( node.type === 'media' ) {
			reference( node.definitionRef, format( '%s.definitionRef', p ), 'definition', state );
		} else if ( node.type === 'code' ) {
			for ( j = 0; j < node.directiveRefs.length; j++ ) {
				reference( node.directiveRefs[ j ], format( '%s.directiveRefs[%d]', p, j ), 'directive', state );
			}
		}
	}
}

/**
* Checks definition index integrity.
*
* @private
* @param {Object} doc - semantic document
* @param {Object} state - validation state
* @returns {void}
*/
function definitionIndex( doc, state ) {
	var definitions;
	var expected;
	var actual;
	var keys;
	var def;
	var key;
	var i;

	definitions = doc.resources.definitions;
	expected = Object.create( null );
	for ( i = 0; i < definitions.length; i++ ) {
		def = definitions[ i ];
		if ( def.selected ) {
			key = def.normalizedIdentifier;
			if ( expected[ key ] ) {
				state.errors.push( error( format( '.resources.definitions[%d].selected', i ), 'duplicate-selected-definition', 'must be the only selected definition for its normalized identifier' ) );
			} else {
				expected[ key ] = def.id;
			}
		}
	}
	actual = doc.resources.definitionIndex;
	keys = objectKeys( expected );
	for ( i = 0; i < keys.length; i++ ) {
		key = keys[ i ];
		if ( actual[ key ] !== expected[ key ] ) {
			state.errors.push( error( '.resources.definitionIndex', 'definition-index', 'must map each selected normalized definition to its resource ID' ) );
		}
	}
	keys = objectKeys( actual );
	for ( i = 0; i < keys.length; i++ ) {
		key = keys[ i ];
		if ( actual[ key ] !== expected[ key ] ) {
			state.errors.push( error( format( '.resources.definitionIndex.%s', key ), 'definition-index', 'must not contain an unselected or mismatched definition' ) );
		}
	}
}

/**
* Checks directive and accounting references.
*
* @private
* @param {Object} doc - semantic document
* @param {Object} state - validation state
* @returns {void}
*/
function resourceReferences( doc, state ) {
	var directives;
	var embedded;
	var target;
	var keys;
	var code;
	var refs;
	var ref;
	var d;
	var p;
	var j;
	var i;

	directives = doc.resources.directives;
	embedded = doc.resources.embeddedCode;
	for ( i = 0; i < embedded.length; i++ ) {
		refs = embedded[ i ].directiveRefs;
		for ( j = 0; j < refs.length; j++ ) {
			reference( refs[ j ], format( '.resources.embeddedCode[%d].directiveRefs[%d]', i, j ), 'directive', state );
		}
	}
	for ( i = 0; i < directives.length; i++ ) {
		d = directives[ i ];
		for ( j = 0; j < d.targetRefs.length; j++ ) {
			ref = d.targetRefs[ j ];
			p = format( '.resources.directives[%d].targetRefs[%d]', i, j );
			code = reference( ref, p, [ 'code', 'embedded-code' ], state );
			if ( !code ) {
				continue;
			}
			if ( code.node.directiveRefs.indexOf( d.id ) === -1 ) {
				state.errors.push( error( p, 'directive-relationship', 'must be mirrored by the target code directiveRefs' ) );
			}
		}
	}
	keys = objectKeys( state.ids );
	for ( i = 0; i < keys.length; i++ ) {
		code = state.ids[ keys[ i ] ];
		if ( code.type === 'code' ) {
			refs = code.node.directiveRefs;
			for ( j = 0; j < refs.length; j++ ) {
				target = state.ids[ refs[ j ] ];
				if (
					target &&
					target.type === 'directive' &&
					target.node.targetRefs.indexOf( code.id ) === -1
				) {
					state.errors.push( error( '.children', 'directive-relationship', 'code directiveRefs must be mirrored by directive targetRefs' ) );
				}
			}
		}
	}
	for ( i = 0; i < embedded.length; i++ ) {
		code = embedded[ i ];
		refs = code.directiveRefs;
		for ( j = 0; j < refs.length; j++ ) {
			target = state.ids[ refs[ j ] ];
			if (
				target &&
				target.type === 'directive' &&
				target.node.targetRefs.indexOf( code.id ) === -1
			) {
				state.errors.push( error( format( '.resources.embeddedCode[%d].directiveRefs[%d]', i, j ), 'directive-relationship', 'embedded code directiveRefs must be mirrored by directive targetRefs' ) );
			}
		}
	}
	for ( i = 0; i < doc.accounting.length; i++ ) {
		refs = doc.accounting[ i ].targetRefs;
		for ( j = 0; j < refs.length; j++ ) {
			reference( refs[ j ], format( '.accounting[%d].targetRefs[%d]', i, j ), TARGET_TYPES, state );
		}
	}
}


// MAIN //

/**
* Validates semantic relationships which JSON Schema cannot express.
*
* @param {Object} doc - schema-valid semantic document
* @returns {Array} integrity errors
*/
function integrity( doc ) {
	var state = {
		'errors': [],
		'ids': Object.create( null ),
		'previous': null
	};
	flow( doc.children, state, '.children' );
	resources( doc, state );
	reference( doc.titleRef, '.titleRef', 'heading', state );
	reference( doc.summaryRef, '.summaryRef', 'summary', state );
	flowReferences( doc.children, state, '.children' );
	definitionIndex( doc, state );
	resourceReferences( doc, state );
	return state.errors;
}


// EXPORTS //

module.exports = integrity;
